<#
  Fix-MapModalAISearch.ps1
  Compatible with Windows PowerShell 5.1 (no PS7-only syntax used).

  Context: this app already combines Mapbox Geocoding + OpenStreetMap
  Nominatim (src\utils\mapbox.js), plus an AI-assisted fallback
  (/api/smart-location-search) that asks Claude to expand a shorthand
  local name (e.g. "Brigade" -> "Brigade Market, Sabon Gari, Kano,
  Nigeria") and re-queries Mapbox with that - only when the direct search
  already came up empty, so it adds no cost on searches that already
  work, and Claude never supplies coordinates itself.

  That fallback was already wired into send-package/step-1 and
  vendor/create-delivery, but MapModal.jsx - the map picker used from the
  vendor dashboard and create-delivery's "open full map" view - never
  got it. A real, well-known place that resolved fine everywhere else in
  the app could still show an empty dropdown specifically inside that
  modal. Fixed by adding the exact same fallback there.

  Writes full file content (base64-encoded, written as raw bytes - no
  PowerShell string-escaping of JS/JSX, no BOM-injection risk). Backs up
  the existing file to .fix-backup-mapmodal-ai-search\ first.

  Run from the ROOT of your local repo clone:
      powershell -ExecutionPolicy Bypass -File .\Fix-MapModalAISearch.ps1
#>

$ErrorActionPreference = "Stop"
$root = Get-Location
$backupDir = Join-Path $root ".fix-backup-mapmodal-ai-search"
if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }

if (-not (Test-Path -LiteralPath (Join-Path $root "src\app"))) {
    Write-Host "ERROR: src\app not found. Run this script from the repo root." -ForegroundColor Red
    exit 1
}

function Get-FullPath($rel) { return Join-Path $root $rel }

function Backup-Path($full) {
    if (Test-Path -LiteralPath $full) {
        $rel = $full.Substring($root.Path.Length).TrimStart('\','/')
        $dest = Join-Path $backupDir $rel
        $destParent = Split-Path $dest -Parent
        if (-not (Test-Path -LiteralPath $destParent)) { New-Item -ItemType Directory -Path $destParent -Force | Out-Null }
        Copy-Item -LiteralPath $full -Destination $dest -Force
    }
}

function Write-FileFromBase64($relPath, $b64) {
    $full = Get-FullPath $relPath
    $targetParent = Split-Path $full -Parent
    if (-not (Test-Path -LiteralPath $targetParent)) { New-Item -ItemType Directory -Path $targetParent -Force | Out-Null }
    Backup-Path $full
    $bytes = [Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  WROTE: $relPath" -ForegroundColor Green
}

Write-Host "`nApplying MapModal AI-search fix:" -ForegroundColor Cyan

$b64_MAPMODAL = ""
Write-FileFromBase64 "src\components\MapModal.jsx" $b64_MAPMODAL

Write-Host "`nDone. Backup saved under .fix-backup-mapmodal-ai-search\" -ForegroundColor Cyan
Write-Host "Next: npm run build (or your usual dev command), then redeploy to Vercel." -ForegroundColor Cyan
